import { asDefined, isDefined, Option, panic } from "@opendaw/lib-std";
import { InferenceCancelledError } from "./Errors";
import { ModelStore } from "./ModelStore";
const NO_PROGRESS = () => { };
export class EngineHost {
    #workerFactory;
    #pending = new Map();
    #loadedTasks = new Set();
    #names = new Map();
    #queue = [];
    #worker = Option.None;
    #ready = Option.None;
    #nextCallId = 1;
    #processing = false;
    constructor(options) {
        this.#workerFactory = options.workerFactory;
    }
    async ensureLoaded(taskKey, model, executionProviders, options) {
        if (this.#loadedTasks.has(taskKey)) {
            options?.progress?.(1.0);
            return;
        }
        const modelBytes = await ModelStore.ensure(taskKey, model, options);
        await this.#ensureWorker();
        this.#throwIfAborted(options?.signal);
        const ack = await this.#dispatch({
            kind: "load",
            id: this.#nextId(),
            taskKey,
            model,
            modelBytes,
            executionProviders
        });
        this.#names.set(taskKey, { inputs: ack.inputs, outputs: ack.outputs });
        this.#loadedTasks.add(taskKey);
    }
    namesFor(taskKey) {
        const names = this.#names.get(taskKey);
        if (isDefined(names)) {
            return names;
        }
        return panic(`Session names not available for task: ${taskKey}`);
    }
    sessionRunFor(taskKey, signal) {
        return async (feeds) => {
            this.#throwIfAborted(signal.unwrapOrUndefined());
            const result = await this.#dispatch({
                kind: "run",
                id: this.#nextId(),
                taskKey,
                feeds
            });
            return result.output;
        };
    }
    enqueue(work) {
        return new Promise((resolve, reject) => {
            const entry = {
                run: async () => {
                    let released = false;
                    const release = () => { released = true; };
                    return work(release)
                        .then(value => resolve(value), reason => reject(reason))
                        .finally(() => {
                        if (!released) {
                            // entry completed without explicit release; that's fine
                        }
                    });
                }
            };
            this.#queue.push(entry);
            void this.#drain();
        });
    }
    async releaseTask(taskKey) {
        if (!this.#loadedTasks.has(taskKey)) {
            return;
        }
        await this.#dispatch({ kind: "release", id: this.#nextId(), taskKey });
        this.#loadedTasks.delete(taskKey);
        this.#names.delete(taskKey);
    }
    async shutdown() {
        if (this.#worker.isEmpty()) {
            return;
        }
        await this.#dispatch({ kind: "shutdown", id: this.#nextId() });
        this.#worker.unwrap().terminate();
        this.#worker = Option.None;
        this.#ready = Option.None;
        this.#loadedTasks.clear();
        this.#pending.clear();
    }
    async #drain() {
        if (this.#processing) {
            return;
        }
        this.#processing = true;
        while (this.#queue.length > 0) {
            const entry = asDefined(this.#queue.shift());
            await entry.run().catch(() => { });
        }
        this.#processing = false;
    }
    #ensureWorker() {
        if (this.#ready.nonEmpty()) {
            return this.#ready.unwrap();
        }
        const worker = this.#workerFactory();
        this.#worker = Option.wrap(worker);
        const promise = new Promise((resolve, reject) => {
            const onMessage = (event) => {
                const msg = event.data;
                if (msg.kind === "ready") {
                    worker.removeEventListener("message", onMessage);
                    worker.addEventListener("message", this.#onMessage);
                    resolve();
                    return;
                }
                if (msg.kind === "error") {
                    reject(new Error(`Worker initialization failed: ${msg.message}`));
                }
            };
            worker.addEventListener("message", onMessage);
            worker.addEventListener("error", (event) => reject(new Error(`Worker error: ${event.message}`)));
            worker.addEventListener("messageerror", () => reject(new Error("Worker sent an undeserialisable message during initialization")));
        });
        // Without this, a crash after init leaves #pending unsettled and #ready resolved forever.
        const onWorkerDeath = (reason) => {
            if (this.#worker.unwrapOrUndefined() !== worker) {
                return;
            }
            worker.terminate();
            this.#worker = Option.None;
            this.#ready = Option.None;
            this.#loadedTasks.clear();
            this.#names.clear();
            this.#rejectAllPending(new Error(reason));
        };
        worker.addEventListener("error", (event) => onWorkerDeath(`Inference worker crashed: ${event.message}`));
        worker.addEventListener("messageerror", () => onWorkerDeath("Inference worker sent an undeserialisable message"));
        this.#ready = Option.wrap(promise);
        return promise;
    }
    #rejectAllPending(error) {
        const pending = Array.from(this.#pending.values());
        this.#pending.clear();
        pending.forEach(entry => entry.reject(error));
    }
    #onMessage = (event) => {
        const msg = event.data;
        if (msg.kind === "ready") {
            return;
        }
        const pending = this.#pending.get(msg.id);
        if (!isDefined(pending)) {
            return;
        }
        this.#pending.delete(msg.id);
        if (msg.kind === "error") {
            pending.reject(new Error(msg.message));
            return;
        }
        if (msg.kind === "ok") {
            pending.resolve(msg);
            return;
        }
        if (msg.kind === "loaded") {
            pending.resolve(msg);
            return;
        }
        if (msg.kind === "result") {
            pending.resolve(msg);
            return;
        }
    };
    async #dispatch(message) {
        await this.#ensureWorker();
        const worker = this.#worker.unwrap("worker");
        return new Promise((resolve, reject) => {
            this.#pending.set(message.id, {
                id: message.id,
                resolve: resolve,
                reject
            });
            worker.postMessage(message);
        });
    }
    #nextId() {
        const id = this.#nextCallId;
        this.#nextCallId = this.#nextCallId + 1;
        return id;
    }
    #throwIfAborted(signal) {
        if (isDefined(signal) && signal.aborted) {
            throw new InferenceCancelledError();
        }
    }
}
export const splitProgress = (overall, downloadShare) => {
    const handler = overall ?? NO_PROGRESS;
    return {
        download: (value) => handler(value * downloadShare),
        inference: (value) => handler(downloadShare + value * (1 - downloadShare))
    };
};
export const runTask = async (host, args) => {
    const overall = args.progress;
    const share = args.downloadShare ?? 0.5;
    const split = splitProgress(overall, share);
    await host.ensureLoaded(args.task.key, args.task.model, args.executionProviders, {
        progress: split.download,
        signal: args.signal.unwrapOrUndefined()
    });
    const session = host.sessionRunFor(args.task.key, args.signal);
    const names = host.namesFor(args.task.key);
    return args.task.run(args.input, {
        session,
        progress: split.inference,
        signal: args.signal,
        inputNames: names.inputs,
        outputNames: names.outputs
    });
};
